```

6. Загрузите изображения: Загрузите изображения, которые будут использоваться в игре «Змейка». В данном примере мы будем использовать изображения в формате PNG:

```C
SDL_Surface* load_image(char* filename) {
    SDL_Surface* loaded_surface = IMG_Load(filename);
    if (loaded_surface == NULL) {
        printf("Unable to load image %s: %s\n", filename, IMG_GetError());
        return NULL;
    }

    SDL_Surface* optimized_surface = SDL_ConvertSurfaceFormat(
